def move_zeroes(nums):
    next_slot = 0                       # everything before this index is a non-zero item, still in its original order
    for i, value in enumerate(nums):
        if value != 0:
            nums[next_slot], nums[i] = nums[i], nums[next_slot]   # the zeros skipped so far end up behind the writer
            next_slot += 1
